from ortools.sat.python import cp_model
import itertools

def solve_girth_degree(n=12, min_deg=3, max_deg=6, min_girth=6):
    model = cp_model.CpModel()
    # edge variables x[i][j] for i<j
    x = {}
    for i in range(n):
        for j in range(i+1, n):
            x[(i,j)] = model.NewBoolVar(f'x_{i}_{j}')

    def get_var(u, v):
        if u < v:
            return x[(u,v)]
        else:
            return x[(v,u)]

    # degree constraints
    for i in range(n):
        deg = sum(get_var(i, j) for j in range(n) if j != i)
        model.Add(deg >= min_deg)
        model.Add(deg <= max_deg)

    # forbid triangles
    for a in range(n):
        for b in range(a+1, n):
            for c in range(b+1, n):
                model.Add(get_var(a,b) + get_var(b,c) + get_var(a,c) <= 2)

    # forbid 4-cycles
    for verts in itertools.combinations(range(n), 4):
        a,b,c,d = verts
        # cycles: a-b-c-d-a, a-b-d-c-a, a-c-b-d-a
        cycles = [
            ((a,b),(b,c),(c,d),(d,a)),
            ((a,b),(b,d),(d,c),(c,a)),
            ((a,c),(c,b),(b,d),(d,a))
        ]
        for cycle in cycles:
            model.Add(sum(get_var(u,v) for u,v in cycle) <= 3)

    # forbid 5-cycles
    for verts in itertools.combinations(range(n), 5):
        a = verts[0]
        for perm in itertools.permutations(verts[1:]):
            b,c,d,e = perm
            if b < e:
                cycle = ((a,b),(b,c),(c,d),(d,e),(e,a))
                model.Add(sum(get_var(u,v) for u,v in cycle) <= 4)

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 30.0
    solver.parameters.num_search_workers = 8
    status = solver.Solve(model)
    print('Status code:', status)
    print('Status name:', solver.StatusName(status))
    if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
        edges = []
        for i in range(n):
            for j in range(i+1, n):
                if solver.Value(x[(i,j)]) == 1:
                    edges.append((i,j))
        print('Found edges:', edges)
        # verify degrees
        degs = [0]*n
        for u,v in edges:
            degs[u] += 1
            degs[v] += 1
        print('Degrees:', degs)
        # verify girth
        # compute shortest cycle length
        import collections
        girth = float('inf')
        for start in range(n):
            # BFS from start
            dist = {start: 0}
            parent = {start: None}
            q = collections.deque([start])
            while q:
                u = q.popleft()
                for v in range(n):
                    if v == u: continue
                    if (u < v and (u,v) not in edges) or (v < u and (v,u) not in edges):
                        continue
                    if v not in dist:
                        dist[v] = dist[u] + 1
                        parent[v] = u
                        q.append(v)
                    elif parent[u] != v and parent.get(v) != u:
                        # found a cycle
                        cycle_len = dist[u] + dist[v] + 1
                        if cycle_len < girth:
                            girth = cycle_len
        print('Girth:', girth)
        return edges
    else:
        print('No solution found within time limit or proven infeasible.')
        return None

edges = solve_girth_degree()
